WITH cleaned AS (SELECT id, price, cost, stock_qty, launch_date, supplier_id, ROUND(stock_qty * 0.9, 2) AS stock_qty_scaled FROM products WHERE supplier_id IS NOT NULL AND launch_date < '2024-09-30'), with_windows AS (SELECT id, price, cost, stock_qty, launch_date, supplier_id, stock_qty_scaled, COUNT(cost) OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_cost, MAX(cost) OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_cost, AVG(cost) OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_cost, SUM(cost) OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_cost, AVG(stock_qty_scaled) OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS stock_qty_scaled_avg_3_prior FROM cleaned), enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY running_count_cost DESC, id) AS event_seq, STDDEV_SAMP(stock_qty) OVER (PARTITION BY supplier_id) AS supplier_id_stddev_samp_stock_qty FROM with_windows), enriched_products AS (SELECT s.*, p2.supplier_name FROM enriched s LEFT JOIN suppliers p2 ON s.supplier_id = p2.id), scored AS (SELECT *, SUM(running_sum_cost) OVER (ORDER BY stock_qty_scaled_avg_3_prior, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_running_sum_cost, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY stock_qty_scaled_avg_3_prior DESC, id) AS seq_no, PERCENT_RANK() OVER (PARTITION BY supplier_id ORDER BY running_avg_cost NULLS LAST) AS running_avg_cost_percent_rank FROM enriched_products), enriched_products_2 AS (SELECT a.id, a.price, a.stock_qty, a.supplier_id, a.stock_qty_scaled, a.running_max_cost, a.running_avg_cost, a.stock_qty_scaled_avg_3_prior, a.supplier_id_stddev_samp_stock_qty, a.running_running_sum_cost, a.seq_no, a.running_avg_cost_percent_rank, d.supplier_name AS supplier_supplier_name, d.rating FROM scored a INNER JOIN suppliers d ON a.supplier_id = d.id) SELECT id, supplier_id, measure, metric_value FROM (SELECT id, supplier_id, running_avg_cost_percent_rank, running_avg_cost, rating FROM enriched_products_2) src UNPIVOT (metric_value FOR measure IN (running_avg_cost_percent_rank, running_avg_cost, rating AS RATING_VAL))
